import {
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  Color
} from 'three/webgpu';
import { uv, vec2, vec4 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const textContent = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textContent.find(t => t.role === 'headline') || textContent[0];
  const headlineText = headlineItem ? headlineItem.text : 'Collection 1';

  // --- STAGE BACKDROP GRADIENT (Designed-for-dark backdrop) ---
  const backGeo = new PlaneGeometry(7, 6);
  const backMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });

  // Custom TSL vertical gradient from ink (#16161d) to surface (#0b0b10)
  const vUv = uv();
  const cBottom = new Color(colors.surface);
  const cTop = new Color(colors.ink);
  backMat.colorNode = vec4(mix(cBottom, cTop, vUv.y), 0.85);

  const backdrop = new Mesh(backGeo, backMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // --- CORE SPRITE ELEMENT ---
  const spriteWidth = 2.0;
  const spriteHeight = (320 / 512) * spriteWidth; // 1.25 height
  const spriteGeo = new PlaneGeometry(spriteWidth, spriteHeight);
  const spriteMat = new MeshBasicNodeMaterial({ transparent: true });

  // Map configuration texture to atlas region [0, 0, 512, 320]
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      spriteMat.map = tex;

      // Compute texture coordinate transform if from an atlas
      const uScale = 512 / tex.image.width;
      const vScale = 320 / tex.image.height;
      const uOffset = 0;
      // Flip V-axis offset since Three.js texture coordinate V=0 is bottom
      const vOffset = 1.0 - vScale;

      spriteMat.positionNode = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));
      spriteMat.needsUpdate = true;
    }).catch(err => console.warn('Failed loading image:', err));
  } else {
    // Fallback solid visual if texture fails or is empty
    spriteMat.colorNode = vec4(new Color(colors.surface), 0.9);
  }

  const spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.position.set(0, 0, 0.01);
  group.add(spriteMesh);

  // --- TYPOGRAPHY (MSDF Text Atlas) ---
  const textContainer = new Group();
  // Using 39px target size as scene scale (~0.24 scene units)
  const textMesh = ctx.fontAtlas.createText(headlineText, {
    fontSize: 0.24,
    color: colors.paper,
    align: 'center'
  });
  textMesh.position.set(0, -0.1, 0.05);
  textContainer.add(textMesh);

  // Accent Line under text
  const accentLineGeo = new PlaneGeometry(0.6, 0.015);
  const accentLineMat = new MeshBasicNodeMaterial({ color: new THREE.Color(colors.accent) });
  const accentLine = new Mesh(accentLineGeo, accentLineMat);
  accentLine.position.set(0, -0.3, 0.05);
  textContainer.add(accentLine);

  group.add(textContainer);

  // --- INTRO / ENTRY MOTION (GSAP) ---
  const timeline = gsap.timeline();
  // Safe scale setup
  group.scale.set(0.01, 0.01, 0.01);

  // Power4 settle animation toward scale 1.0
  timeline.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 1.1,
    ease: 'power4.out'
  });

  // Soft fade up for text
  textContainer.position.y = -0.15;
  timeline.to(textContainer.position, {
    y: 0,
    duration: 0.8,
    ease: 'power3.out'
  }, 0.2);

  // Cleanup handler
  group.userData = {
    handlers: {},
    cleanup: () => {
      timeline.kill();
      spriteGeo.dispose();
      spriteMat.dispose();
      backGeo.dispose();
      backMat.dispose();
      accentLineGeo.dispose();
      accentLineMat.dispose();
    }
  };

  return group;
}
